class Skiplist {
private:
    struct Node {
        int val;
        vector<Node*> forward;
        Node(int v, int level) : val(v), forward(level, nullptr) {}
    };

    Node* head;
    int maxLevel;
    int curLevel;

    int randomLevel() {
        int lvl = 1;
        while ((rand() & 1) && lvl < maxLevel) {
            lvl++;
        }
        return lvl;
    }

public:
    Skiplist() {
        maxLevel = 32;
        curLevel = 1;
        head = new Node(0, maxLevel);
    }

    bool search(int target) {
        Node* cur = head;
        for (int i = curLevel - 1; i >= 0; i--) {
            while (cur->forward[i] && cur->forward[i]->val < target) {
                cur = cur->forward[i];
            }
        }
        cur = cur->forward[0];
        return cur && cur->val == target;
    }

    void add(int num) {
        vector<Node*> update(maxLevel, nullptr);
        Node* cur = head;
        for (int i = curLevel - 1; i >= 0; i--) {
            while (cur->forward[i] && cur->forward[i]->val < num) {
                cur = cur->forward[i];
            }
            update[i] = cur;
        }
        int lvl = randomLevel();
        if (lvl > curLevel) {
            for (int i = curLevel; i < lvl; i++) {
                update[i] = head;
            }
            curLevel = lvl;
        }
        Node* newNode = new Node(num, lvl);
        for (int i = 0; i < lvl; i++) {
            newNode->forward[i] = update[i]->forward[i];
            update[i]->forward[i] = newNode;
        }
    }

    bool erase(int num) {
        vector<Node*> update(maxLevel, nullptr);
        Node* cur = head;
        for (int i = curLevel - 1; i >= 0; i--) {
            while (cur->forward[i] && cur->forward[i]->val < num) {
                cur = cur->forward[i];
            }
            update[i] = cur;
        }
        cur = cur->forward[0];
        if (!cur || cur->val != num) return false;
        for (int i = 0; i < curLevel; i++) {
            if (update[i]->forward[i] != cur) break;
            update[i]->forward[i] = cur->forward[i];
        }
        delete cur;
        while (curLevel > 1 && head->forward[curLevel - 1] == nullptr) {
            curLevel--;
        }
        return true;
    }
};
